      <a href="register.html" class="btn btn-primary">Register Now</a>`;
    return;
  }

  const initials = `${p.firstName[0] || ""}${p.lastName[0] || ""}`.toUpperCase();
  const rows = [
    ["Student ID", p.studentId], ["Email", p.email], ["Year", p.year],
