const { JSDOM } = require("jsdom");
const fs = require("fs"); const path = require("path");
const root = process.argv[2];
let store = {};
function load(page) {
  return new Promise((res) => {
    const html = fs.readFileSync(path.join(root, page), "utf8")
      .replace(/<script src="([^"]+)"><\/script>/g, (_, s) => `<script>${fs.readFileSync(path.join(root, s), "utf8")}</script>`);
    const errors = [];
    const dom = new JSDOM(html, { runScripts: "dangerously", url: "http://localhost/" + page,
      beforeParse(w) { for (const k in store) w.localStorage.setItem(k, store[k]); w.scrollTo = () => {}; } , virtualConsole: new (require("jsdom").VirtualConsole)().on("jsdomError", e => errors.push(e.message)) });
    dom.window.addEventListener("load", () => res({ w: dom.window, d: dom.window.document, errors }));
  });
}
const save = (w) => { store = {}; for (let i = 0; i < w.localStorage.length; i++) { const k = w.localStorage.key(i); store[k] = w.localStorage.getItem(k); } };
(async () => {
  let { w, d, errors } = await load("index.html");
  console.log("home cards", d.querySelectorAll("#featured-grid .course-card").length, "depts", d.querySelectorAll(".dept-tile").length, "nav", d.querySelectorAll(".nav-links a").length, errors);

  ({ w, d, errors } = await load("catalog.html?q=calc"));
  console.log("catalog search calc ->", d.querySelectorAll(".course-card").length, d.getElementById("result-count").textContent);
  d.getElementById("search").value = ""; d.getElementById("search").dispatchEvent(new w.Event("input"));
  d.getElementById("dept").value = "CS"; d.getElementById("dept").dispatchEvent(new w.Event("change"));
  console.log("CS ->", d.querySelectorAll(".course-card").length);
  d.querySelector('[data-day="Fri"]').click();
  console.log("CS+Fri ->", d.querySelectorAll(".course-card").length, errors);

  ({ w, d, errors } = await load("register.html?course=CS101"));
  console.log("preselected", d.querySelectorAll(".pick.checked").length);
  d.querySelector("#register-form").dispatchEvent(new w.Event("submit", { cancelable: true }));
  console.log("invalid fields", d.querySelectorAll(".field.invalid").length);
  const set = (id, v) => { d.getElementById(id).value = v; };
  set("firstName", "Alex"); set("lastName", "<b>Kim</b>"); set("studentId", "S2024001"); set("email", "alex@uni.edu"); set("program", "Mathematics"); set("studyYear", "Junior");
  const mathcb = d.querySelector('#course-picker input[value="MATH330"]'); // Mon/Wed 10:30 - no conflict with CS101 9:00-10:15
  mathcb.checked = true; mathcb.dispatchEvent(new w.Event("change", { bubbles: true }));
  const conf = d.querySelector('#course-picker input[value="BUS100"]'); conf.checked = true; conf.dispatchEvent(new w.Event("change", { bubbles: true }));
  console.log("alerts:", d.getElementById("summary-alerts").textContent.trim());
  conf.checked = false; conf.dispatchEvent(new w.Event("change", { bubbles: true }));
  const c2 = d.querySelector('#course-picker input[value="PSY101"]'); c2.checked = true; c2.dispatchEvent(new w.Event("change", { bubbles: true }));
  console.log("conflict alerts:", d.getElementById("summary-alerts").textContent.trim());
  c2.checked = false; c2.dispatchEvent(new w.Event("change", { bubbles: true }));
  d.getElementById("terms").checked = true;
  d.querySelector("#register-form").dispatchEvent(new w.Event("submit", { cancelable: true }));
  console.log("modal:", d.getElementById("modal-overlay").classList.contains("show"), d.getElementById("modal-title").textContent);
  d.getElementById("modal-confirm").click();
  await new Promise(r => setTimeout(r, 400));
  console.log("success modal:", d.getElementById("modal-title").textContent, "badge", d.getElementById("nav-badge")?.textContent, errors);
  save(w);

  ({ w, d, errors } = await load("profile.html"));
  console.log("profile name:", d.querySelector("#profile-card h2").innerHTML, "rows", d.querySelectorAll("#course-table tbody tr").length, "foot", d.querySelector("tfoot").textContent.replace(/\s+/g," "));
  d.querySelector('th[data-sort="credits"]').click();
  console.log("sorted", [...d.querySelectorAll("tbody .code-pill")].map(e => e.textContent));
  d.querySelector("[data-drop]").click(); d.getElementById("modal-confirm").click();
  console.log("after drop rows", d.querySelectorAll("#course-table tbody tr").length, "week slots", d.querySelectorAll(".week-slot").length, errors);
  save(w);
  ({ w, d, errors } = await load("catalog.html"));
  console.log("catalog registered btns", d.querySelectorAll(".btn-success").length);
  d.querySelector('[data-action="register"][data-code="PSY101"]').click();
  console.log("quick register modal:", d.getElementById("modal-title").textContent, errors);
})();
EOF
